/* 工場内部ウォークスルー（背景デモ用）: BIM 表示のまま、作業者目線で通路を自動で歩く */
window.__ydbg={ get ctx(){ return ctx; }, get v3(){ return v3; }, canWalk:function(x,z){ return v3CanWalk(x,z); }, get camGoal(){ return camGoal; } };
window.__ywalkStart=function(){
  if(!ctx||ctx.kind!=='interior') return false;
  var W=ctx.W, D=ctx.D, st=1;
  var nx=Math.max(2,Math.floor(W-2)), nz=Math.max(2,Math.floor(D-2));
  function cx(i){ return -W/2+1+i*st; } function cz(j){ return -D/2+1+j*st; }
  function ok(x,z){ return v3CanWalk(x,z)&&v3CanWalk(x+.6,z)&&v3CanWalk(x-.6,z)&&v3CanWalk(x,z+.6)&&v3CanWalk(x,z-.6); }
  var free=[]; for(var i=0;i<nx;i++){ free.push([]); for(var j=0;j<nz;j++) free[i][j]=ok(cx(i),cz(j)); }
  /* 周囲 8 近傍がすべて空いているセルは通路の真ん中とみなし、そこを優先して通る */
  var cost=[]; for(var i=0;i<nx;i++){ cost.push([]); for(var j=0;j<nz;j++){ var open=0; for(var a=-1;a<=1;a++) for(var b=-1;b<=1;b++){ var ii=i+a, jj=j+b; if(ii>=0&&jj>=0&&ii<nx&&jj<nz&&free[ii][jj]) open++; } cost[i][j]= open===9 ? 1 : (open>=7 ? 1.5 : 4); } }
  function key(c){ return c[0]+','+c[1]; }
  var dirs=[[1,0],[-1,0],[0,1],[0,-1]];
  function bfs(s){ var prev=new Map(), q=[s], h=0; prev.set(key(s),null);
    while(h<q.length){ var c=q[h++]; for(var k=0;k<4;k++){ var n=[c[0]+dirs[k][0],c[1]+dirs[k][1]];
      if(n[0]<0||n[1]<0||n[0]>=nx||n[1]>=nz||!free[n[0]][n[1]]||prev.has(key(n))) continue; prev.set(key(n),c); q.push(n); } }
    return prev; }
  /* コスト付き最短路（ダイクストラ、小さな格子なので単純実装） */
  function route(s,t){ var dist=new Map(), prev=new Map(), open=[s]; dist.set(key(s),0); prev.set(key(s),null);
    while(open.length){ var bi=0; for(var q=1;q<open.length;q++) if(dist.get(key(open[q]))<dist.get(key(open[bi]))) bi=q; var c=open.splice(bi,1)[0]; if(c[0]===t[0]&&c[1]===t[1]) break; var dc=dist.get(key(c));
      for(var k=0;k<4;k++){ var n=[c[0]+dirs[k][0],c[1]+dirs[k][1]]; if(n[0]<0||n[1]<0||n[0]>=nx||n[1]>=nz||!free[n[0]][n[1]]) continue; var nd=dc+cost[n[0]][n[1]]; var kn=key(n); if(!dist.has(kn)||nd<dist.get(kn)){ dist.set(kn,nd); prev.set(kn,c); if(!open.some(function(o){ return o[0]===n[0]&&o[1]===n[1]; })) open.push(n); } } }
    if(!prev.has(key(t))) return null; var out=[], c2=t; while(c2){ out.unshift(c2); c2=prev.get(key(c2)); } return out; }
  /* 最大の連結領域を使う */
  var seen=new Set(), bestSet=null;
  for(var i=0;i<nx;i++) for(var j=0;j<nz;j++){ if(!free[i][j]||seen.has(i+','+j)) continue; var pv=bfs([i,j]); pv.forEach(function(_,k){ seen.add(k); }); if(!bestSet||pv.size>bestSet.size) bestSet=pv; }
  if(!bestSet||bestSet.size<12) return false;
  var cells=[]; bestSet.forEach(function(_,k){ cells.push(k.split(',').map(Number)); });
  function nearest(tx,tz){ var b=null, bd=1e9; cells.forEach(function(p){ var dd=Math.hypot(cx(p[0])-tx,cz(p[1])-tz)+(cost[p[0]][p[1]]-1)*0.6; if(dd<bd){ bd=dd; b=p; } }); return b; }
  /* 右通路を南下 → 充填ラインと製品列のあいだを縫って南端へ → 左通路を北上 → 搬入口前を東へ → 戻る */
  var start=nearest(W*.368, -D*.31);
  var wps=[[W*.368,D*.138],[0,D*.147],[W*.016,D*.224],[W*.042,D*.302],[0,D*.397],[-W*.368,D*.397],[-W*.368,-D*.466],[W*.368,-D*.466]].map(function(t){ return nearest(t[0],t[1]); });
  var seq=[start].concat(wps,[start]), pts=[];
  for(var k=0;k<seq.length-1;k++){ var pp=route(seq[k],seq[k+1]); if(!pp) continue; if(pts.length) pp.shift(); pts=pts.concat(pp); }
  if(pts.length<6) return false;
  var P=pts.map(function(c){ return [cx(c[0]),cz(c[1])]; });
  /* 角を少し丸める（1セル=1m、クリアランス0.6mの範囲内） */
  var S=P.map(function(p,i){ var a=P[(i-1+P.length)%P.length], b=P[(i+1)%P.length]; return [(a[0]+2*p[0]+b[0])/4,(a[1]+2*p[1]+b[1])/4]; });
  var segLen=S.map(function(p,i){ var q=S[(i+1)%S.length]; return Math.hypot(q[0]-p[0],q[1]-p[1]); });
  var total=segLen.reduce(function(a,b){ return a+b; },0);
  function at(dist){ dist=((dist%total)+total)%total; var i=0; while(dist>segLen[i]){ dist-=segLen[i]; i=(i+1)%S.length; } var p=S[i], q=S[(i+1)%S.length], t=segLen[i]>1e-6?dist/segLen[i]:0; return [p[0]+(q[0]-p[0])*t, p[1]+(q[1]-p[1])*t]; }
  var SPEED=0.95, LOOK=3.0, dist=0, time=0;
  function headingAt(d){ var a=at(d), b=at(d+LOOK); return Math.atan2(b[1]-a[1], b[0]-a[0]); }
  scene.traverse(function(o){ if(o.isSprite) o.visible=false; });   // 名称ラベル（スプライト）は出さない
  v3ClearSection(); select(null); v3.walk=true; v3.keys.clear(); document.body.classList.add('v3-walk');
  var p0=at(0); v3.walkPos.set(p0[0],1.62,p0[1]);
  camGoal.yaw=headingAt(0); camGoal.pitch=1.38; autoOrbit=false;
  window.__ywalkTick=function(dt){
    if(!v3.walk||!window.__YGO) return;
    time+=dt; dist+=dt*SPEED;
    var p=at(dist); v3.walkPos.set(p[0], 1.62+Math.sin(time*2.4)*0.012, p[1]);
    var want=headingAt(dist)+Math.sin(time*0.35)*0.3;                  // 進行方向＋ゆっくり見回す
    var dy=Math.atan2(Math.sin(want-camGoal.yaw), Math.cos(want-camGoal.yaw));
    camGoal.yaw+=dy*Math.min(1, dt*1.6);
    camGoal.pitch=1.38+Math.sin(time*0.5)*0.05;
  };
  return true;
};

